resources.text:
.glass {
  background: linear-gradient(145deg, var(--ui-hi), transparent 42%), var(--ui-bg);
  border: 1px solid var(--ui-border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

.panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--muted);
  margin-bottom: 10px;
}

.panel-title kbd {
  font: inherit;
  border: 1px solid var(--ui-border);
  border-radius: 5px;
  padding: 1px 5px;
}

.rp-panel {
  position: fixed; left: 16px; right: 16px; bottom: calc(var(--v-dock-h, 54px) + 14px); z-index: 40;
  max-width: 1000px; margin: 0 auto; max-height: calc(100vh - var(--v-dock-h, 54px) - var(--v-hud-h, 46px) - 30px); overflow: auto;
  display: grid; gap: 8px; padding: 12px 14px 14px;
  /* Nearly opaque: a panel this full of drawing must not show the tool bars through it. */
  background: rgba(14, 22, 24, 0.97); color: var(--v-text, #eef4f2);
  border: 1px solid var(--v-line, rgba(255, 255, 255, 0.1)); border-radius: var(--v-r, 12px);
  box-shadow: var(--v-shadow, 0 18px 50px rgba(0, 0, 0, 0.45));
  font: 13px/1.3 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif;
}

.rp-keys {
  position: fixed; left: 330px; bottom: 80px; z-index: 41; width: 264px; display: grid; gap: 8px; padding: 12px;
  background: rgba(14, 22, 24, 0.97); color: var(--v-text, #eef4f2); border: 1px solid var(--v-line, rgba(255,255,255,.1));
  border-radius: var(--v-r, 12px); box-shadow: var(--v-shadow, 0 18px 50px rgba(0,0,0,.45));
  font: 13px/1.3 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif;
}

.v2-icon > span, .v2-pill > span, .v2-seg-b > span, .v2-tabs.compact .v2-tab.icon:not(.on) > span, .v2-tabs.tight .v2-tab.icon > span, .v2-choice.icon > span,
.v2-verb > span, .v2-act > span {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;
}

.v2-seg-b, .v2-speed-b {
  position: relative; display: grid; place-items: center; min-width: 34px; height: 28px; padding: 0 6px;
  border: 0; border-radius: 999px; background: none; color: var(--v-muted); font-weight: 700; font-size: 14px;
}
